      "desc": "青基地前は工場街、橙拠点前は住宅地。工場の隙間・連絡橋下・住宅の路地・屋根を使って接近し、正面ゲートの強行突破や側面侵入を選ぶ。 橙基地の陸側には14mの尾根。山腹から側壁を越え、基地内の斜面へ下る侵入路がある。 中央は左手前から右奥へ斜めに渡る22m高架。B–C間は地上防壁・橋上塔・積み荷で射線を折り、両脇を通れる。 複路争奪。勝率未確定。"
